import json,tarfile,collections;out={};
with tarfile.open('assets/training/selftrained-v2.tar.gz','r:gz') as t:
 for s in ['train','validation','test']:
  ds=[json.loads(x) for x in t.extractfile('voice-'+s+'.jsonl').read().splitlines() if x.strip()];g=collections.defaultdict(set)
  for d in ds:g[d['group_id']].add(d['audio'])
  out[s]={'rows':len(ds),'original_source_groups':len(g),'derived_or_original_audio_paths':len({d['audio'] for d in ds}),'audio_paths_per_original_group':dict(collections.Counter(len(v) for v in g.values()))}
print(json.dumps(out));assert [out[s]['original_source_groups'] for s in ['train','validation','test']]==[62,15,30]
